package com.supermercado.pos.ui;

import javax.swing.*;import java.util.*;import com.supermercado.pos.servicio.*;
public class ReversionFrame extends JFrame {public ReversionFrame(){super("Reversión de venta");UI.permiso("REVERSION_SOLICITAR");JPanel p=UI.panel();JTextField detalle=UI.campo(p,"ID detalle de venta");JTextField cantidad=UI.campo(p,"Cantidad a revertir");JTextField motivo=UI.campo(p,"Motivo");JButton ver=new JButton("Ver detalles");JButton revertir=new JButton("Solicitar autorización");p.add(ver);p.add(revertir);ver.addActionListener(e->UI.mostrar("Detalles","SELECT d.id,d.venta_id,d.producto_id,d.cantidad,d.cantidad_reversada FROM venta_detalle d ORDER BY d.id DESC FETCH FIRST 30 ROWS ONLY"));revertir.addActionListener(e->UI.accion(this,()->{AutorizacionDialog a=new AutorizacionDialog(this);a.setVisible(true);if(a.usuario==null)return;try{Operaciones.revertir(Long.parseLong(detalle.getText()),Integer.parseInt(cantidad.getText()),motivo.getText(),a.usuario,a.clave);UI.mensaje(this,"Reversión registrada");}finally{Arrays.fill(a.clave,'\0');}}));add(p);pack();setLocationRelativeTo(null);}}